args.streamContent:
import { cacheTag } from "next/cache";
import { getAllProducts } from "@/lib/db";

async function ProductListing() {
  "use cache";
  cacheTag("products");

  const products = await getAllProducts();

  return (
    <ul className="space-y-2">
      {products.map((product) => (
        <li
          key={product.id}
          className="rounded-lg border p-4 bg-white shadow-sm"
        >
          <h3 className="font-semibold">{product.name}</h3>
          <p className="text-sm text-gray-600">{product.description}</p>
          <p className="mt-2 font-medium text-green-600">
            ${product.price.toFixed(2)}
          </p>
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  return (
    <div className="min-h-screen p-8 max-w-2xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">Product Listing</h1>

      <ProductListing />

      <form
        action={async () => {
          "use server";
          const { updateTag } = await import("next/cache");
          updateTag("products");
        }}
        className="mt-8 p-4 rounded-lg border bg-gray-50"
      >
        <h2 className="font-semibold mb-2">Cache Invalidation</h2>
        <p className="text-sm text-gray-600 mb-4">
          Submit this form to invalidate the products cache. The next request
          will fetch fresh data from the database.
        </p>
        <button
          type="submit"
          className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
        >
          Invalidate Products Cache
        </button>
      </form>
    </div>
  );
}

